// Fake `az` (Azure CLI) for Windows CI. Unlike the npm shims, az.cmd here is a plain batch file, as the real az.cmd is
// (it runs Python), so `az` is started through cmd.exe with the CmdShimGuard checks, the way the real one is.
//
// `az account get-access-token --resource https://cognitiveservices.azure.com --query accessToken -o tsv` prints a
// made-up token followed by CR LF, or, with FAKE_AZ_LOGGED_OUT set, fails the way az does before `az login`.
'use strict';
const { EOL, record } = require('fake-common');

const argv = process.argv.slice(2);
record('az', argv);
const expected = ['account', 'get-access-token', '--resource', 'https://cognitiveservices.azure.com', '--query', 'accessToken', '-o', 'tsv'];
if (argv[0] === '--version') {
  process.stdout.write('azure-cli (fake) 0.0.1' + EOL);
  process.exit(0);
}
if (JSON.stringify(argv) !== JSON.stringify(expected)) {
  process.stderr.write(`ERROR: fake az: unexpected arguments ${JSON.stringify(argv)}` + EOL);
  process.exit(2);
}
if (process.env.FAKE_AZ_LOGGED_OUT) {
  process.stderr.write("ERROR: Please run 'az login' to setup account." + EOL);
  process.exit(1);
}
process.stdout.write('fake-az-token-0123456789' + EOL);
process.exit(0);
